(function(global){
'use strict';
if(!global.PoolShedInventoryControl||typeof renderLocations!=='function')return;
const inv=global.PoolShedInventoryControl;
const baseLocationFormRenderer=renderLocations;
function legacyRenderLocations(){const result=baseLocationFormRenderer();document.getElementById('screen-locations')?.classList?.add('ps-workspace-compat');return result;}
const legacySidebarSubGroups=typeof sidebarSubGroups==='function'?sidebarSubGroups:null;
const legacyOpenSidebarSubGroup=typeof openSidebarSubGroup==='function'?openSidebarSubGroup:null;
const sections=['Locations','Engineer Vans','Project Stock','Stock','Overview','Transfers & Top-Ups','Cycle Counts','Missing / Damaged','Stock Movements','Exceptions & Alerts'];
const state=global.poolShedInventoryV112State||{locationId:'',query:'',locationType:'',alertFilter:'all',profilePreview:'',smartMinProductId:'',remindersDay:''};
global.poolShedInventoryV112State=state;
function d(){return typeof global.__POOL_SHED_GET_DATA__==='function'?(global.__POOL_SHED_GET_DATA__()||{}):data;}
function esc(v){return typeof escapeHtml==='function'?escapeHtml(String(v==null?'':v)):String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function cash(v){return typeof money==='function'?money(Number(v||0)):new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(v||0));}
function n(v){const x=Number(v);return Number.isFinite(x)?x:0;}
function notify(msg){if(typeof toast==='function')toast(msg);}
function save(){if(typeof saveAppData==='function')saveAppData();}
function pill(label,tone){return '<span class="inv-pill '+esc(tone||'info')+'">'+esc(label)+'</span>';}
function current(){return (activeSubPage&&activeSubPage.locations)||'Locations';}
function setSection(name){activeSubPage.locations=name;inventoryView='overview';selectedInventoryLocationId='';state.locationId='';render();}
function locName(id){const l=inv.location(id);return l?l.name:id;}
function typeTone(type){const t=String(type||'').toLowerCase();if(t.includes('engineer'))return 'blue';if(t.includes('job'))return 'purple';if(t.includes('quarantine'))return 'bad';if(t.includes('warehouse'))return 'good';return 'info';}
function healthTone(row){return row.belowMin?'bad':row.overMax?'warn':row.projectDemand>row.available?'warn':'good';}
function lastMovement(productId,locationId){const loc=inv.location(locationId);return (d().movements||[]).filter(m=>m&&m.productId===productId&&(m.from===locationId||m.to===locationId||m.from===loc?.name||m.to===loc?.name)).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0]||null;}
function openPoForProduct(productId){return (d().purchaseOrders||[]).filter(po=>po&&!['Cancelled','Closed','Received'].includes(po.status)&&(po.lines||[]).some(line=>line.productId===productId&&n(line.qty)>n(line.received))).sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999')))[0]||null;}
function searchMatch(){const q=state.query.trim().toLowerCase();return function(values){return !q||values.filter(Boolean).join(' ').toLowerCase().includes(q);};}
function inventoryNav(){return ''; /* Module destinations belong to the left menu. */}
function header(title,intro,actions){return '<header class="inventory-head"><div><span class="inventory-kicker">INVENTORY / LOCATION CONTROL</span><h1>'+esc(title)+'</h1><p>'+esc(intro)+'</p></div><div class="inventory-head-actions">'+(actions||'')+'</div></header>'+inventoryNav();}
function companyMetrics(){const locs=d().locations||[],rows=d().stock||[];const onHand=rows.reduce((x,r)=>x+n(r.qty),0),allocated=rows.reduce((x,r)=>x+n(r.allocated),0),available=rows.reduce((x,r)=>x+Math.max(0,n(r.qty)-n(r.allocated)),0),value=rows.reduce((x,r)=>{const p=(d().products||[]).find(p=>p.id===r.productId);return x+n(r.qty)*n(p?.cost);},0),alerts=inv.alerts();return '<section class="inventory-metrics"><div><span>On Hand</span><strong>'+onHand+'</strong><small>'+locs.length+' locations</small></div><div><span>Allocated</span><strong>'+allocated+'</strong><small>committed stock</small></div><div><span>Available</span><strong>'+available+'</strong><small>free to use</small></div><div><span>Stock value</span><strong>'+cash(value)+'</strong><small>cost basis</small></div><div><span>Exceptions</span><strong>'+alerts.filter(a=>a.severity!=='info').length+'</strong><small>need review</small></div></section>';}
function locationRowsTable(locs){const match=searchMatch();const rows=locs.filter(l=>match([l.name,l.type,l.owner,l.barcode])).map(l=>{const s=inv.locationSummary(l.id),read=String(l.type)==='Engineer Van'?inv.vanReadiness(l.id):null;return '<tr><td><button class="link-button inv-location-link" data-inv-open-location="'+esc(l.id)+'"><strong>'+esc(l.name)+'</strong></button><small>'+esc(l.owner||'')+' · '+esc(l.barcode||'No barcode')+'</small></td><td>'+pill(l.type,typeTone(l.type))+'</td><td><strong>'+s.onHand+'</strong><small>'+s.allocated+' allocated</small></td><td><strong>'+s.available+'</strong><small>'+cash(s.stockValue)+' value</small></td><td><strong>'+s.lowLines+'</strong><small>'+s.topUpUnits+' units to Target</small></td><td><strong>'+s.overLines+'</strong><small>'+s.returnUnits+' return suggested</small></td><td><strong>'+(read?read.readinessPct+'%':s.count.due?'Count due':'Current')+'</strong><small>'+(read?read.belowMin+' below Min':(s.count.lastCounted||'Not counted'))+'</small></td><td>'+pill(s.count.due?'Count due':'Healthy',s.count.due?'warn':'good')+'</td><td class="right"><button data-inv-open-location="'+esc(l.id)+'">Open</button></td></tr>';}).join('')||'<tr><td colspan="9" class="inv-empty">No locations match the current filters.</td></tr>';return '<div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Location</th><th>Type</th><th>On Hand</th><th>Available</th><th>Below Min</th><th>Over Target</th><th>Readiness</th><th>Count</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';}
function locationFilters(){const types=[...new Set((d().locations||[]).map(l=>l.type).filter(Boolean))].sort();return '<div class="inventory-toolbar"><div class="inventory-search"><span>⌕</span><input data-inv-search placeholder="Search location, engineer, barcode…" value="'+esc(state.query)+'"></div><select data-inv-location-type><option value="">All location types</option>'+types.map(t=>'<option '+(state.locationType===t?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select><button class="secondary" data-inv-manage-locations>Manage locations</button></div>';}
function locationsPage(filterType){let locs=d().locations||[];if(filterType)locs=locs.filter(l=>l.type===filterType);if(state.locationType)locs=locs.filter(l=>l.type===state.locationType);const title=filterType==='Engineer Van'?'Engineer Vans':filterType==='Job Bin'?'Project Stock':'Locations';const intro=filterType==='Engineer Van'?'Treat every engineer van as a managed mini-warehouse with Min, Target, Max, counts and Project demand.':filterType==='Job Bin'?'See live Project-held stock and jump directly to the Project that owns it.':'Physical stock authority across warehouses, bins, vans, Project Job Bins, sites, receiving and quarantine.';return header(title,intro,'<button class="secondary" data-inv-open-warehouse>Open Warehouse</button>')+companyMetrics()+locationFilters()+locationRowsTable(locs);}
function locationDetail(locationId){const loc=inv.location(locationId);if(!loc)return locationsPage();const s=inv.locationSummary(locationId),rows=inv.locationRows(locationId),read=loc.type==='Engineer Van'?inv.vanReadiness(locationId):null,demands=new Map(inv.projectDemandForLocation(locationId).map(x=>[x.productId,x]));const alerts=inv.alerts().filter(a=>a.locationId===locationId),smart=loc.type==='Engineer Van'?inv.smartThresholdSuggestions(locationId):[];const metrics='<section class="inventory-location-metrics"><div><span>On Hand</span><strong>'+s.onHand+'</strong></div><div><span>Allocated / Project</span><strong>'+s.allocated+'</strong></div><div><span>Available</span><strong>'+s.available+'</strong></div><div><span>Stock value</span><strong>'+cash(s.stockValue)+'</strong></div><div><span>Below Min</span><strong>'+s.lowLines+'</strong></div><div><span>Top-up required</span><strong>'+s.topUpUnits+'</strong></div><div><span>Count status</span><strong>'+(s.count.due?'Due':'Current')+'</strong></div>'+(read?'<div><span>Core readiness</span><strong>'+read.readinessPct+'%</strong></div>':'')+'</section>';
 const table=rows.map(r=>{const mv=lastMovement(r.productId,locationId),dem=demands.get(r.productId),move=r.suggestedTopUp>0?'+ '+r.suggestedTopUp+' from Warehouse':r.returnSuggested>0?'- '+r.returnSuggested+' to Warehouse':r.projectDemand>r.available?'Stage '+(r.projectDemand-r.available):'—';return '<tr><td><button class="link-button" data-inv-open-product="'+esc(r.productId)+'"><strong>'+esc(r.name)+'</strong></button><small>'+esc(r.sku)+'</small></td><td>'+r.onHand+'</td><td>'+r.allocated+'</td><td><strong>'+r.available+'</strong></td><td><input class="inv-threshold-input" type="number" min="0" value="'+r.min+'" data-inv-threshold="'+esc(r.productId)+'|'+esc(locationId)+'|min"></td><td><input class="inv-threshold-input" type="number" min="0" value="'+r.target+'" data-inv-threshold="'+esc(r.productId)+'|'+esc(locationId)+'|restockTo"></td><td><input class="inv-threshold-input" type="number" min="0" value="'+r.max+'" data-inv-threshold="'+esc(r.productId)+'|'+esc(locationId)+'|max"></td><td><strong>'+r.projectDemand+'</strong>'+(dem&&dem.jobs.length?'<small><button class="link-button" data-inv-open-project="'+esc(dem.jobs[0])+'">'+esc(dem.jobs.join(', '))+'</button></small>':'<small>No open Project demand</small>')+'</td><td><strong>'+esc(move)+'</strong><small>'+r.warehouseAvailable+' free in Warehouse</small></td><td>'+esc(mv?.date||'—')+'<small>'+esc(mv?.type||'No movement')+'</small></td><td>'+(s.count.due?pill('Count Due','warn'):pill('Current','good'))+'</td><td>'+pill(r.status,healthTone(r))+'</td><td class="right"><div class="inv-row-actions">'+(r.suggestedTopUp>0?'<button data-inv-topup="'+esc(locationId)+'|'+esc(r.productId)+'|'+r.suggestedTopUp+'">Top up</button>':'')+(r.returnSuggested>0?'<button class="secondary" data-inv-return="'+esc(locationId)+'|'+esc(r.productId)+'|'+r.returnSuggested+'">Return</button>':'')+'<button class="secondary" data-inv-save-threshold="'+esc(r.productId)+'|'+esc(locationId)+'">Save Min/Target</button></div></td></tr>';}).join('')||'<tr><td colspan="13" class="inv-empty">No stock or threshold rules at this location.</td></tr>';
 const alertHtml=alerts.length?alerts.map(a=>'<div class="inventory-alert '+esc(a.severity)+'"><div><strong>'+esc(a.title)+'</strong><p>'+esc(a.reason)+'</p></div>'+alertAction(a)+'</div>').join(''):'<div class="inventory-empty-card">No active location exceptions.</div>';
 const profile=loc.type==='Engineer Van'?vanProfilePanel(loc,smart):'';
 return header(loc.name,loc.type+' · '+(loc.owner||'')+' · Location stock, thresholds, demand and count control.','<button class="secondary" data-inv-back-locations>← Locations</button><button data-inv-start-count="'+esc(loc.id)+'">Start / Continue Count</button>')+metrics+'<section class="inventory-detail-grid"><main><section class="inventory-card"><header><div><h2>Location Stock Control</h2><p>Min / Target / Max is location-specific. Reserved Project stock is excluded from free van readiness.</p></div></header><div class="inventory-table-wrap"><table class="inventory-table inventory-location-stock"><thead><tr><th>Product</th><th>On Hand</th><th>Reserved / Project</th><th>Available</th><th>Min</th><th>Target</th><th>Max</th><th>Upcoming Demand</th><th>Suggested Move</th><th>Last Movement</th><th>Count Due</th><th>Status</th><th></th></tr></thead><tbody>'+table+'</tbody></table></div></section>'+profile+'</main><aside><section class="inventory-card"><header><div><h2>Insights & Alerts</h2><p>Problem → reason → next action.</p></div></header><div class="inventory-alert-list">'+alertHtml+'</div></section><section class="inventory-card"><header><div><h2>Location controls</h2></div></header><div class="inventory-control-list"><button data-inv-start-count="'+esc(loc.id)+'">Cycle count</button><button class="secondary" data-inv-open-transfers="'+esc(loc.id)+'">Transfers & Top-Ups</button>'+(loc.type==='Engineer Van'?'<button class="secondary" data-inv-open-replenishment>Supplier replenishment gaps</button>':'')+'</div></section></aside></section>';
}
function vanProfilePanel(loc,smart){const profiles=Object.keys(inv.profiles);return '<section class="inventory-card inventory-van-tools"><header><div><h2>Engineer Van Tools</h2><p>Profiles and Smart Min are advisory until you explicitly apply them.</p></div></header><div class="inventory-van-tool-grid"><div><h3>Van stock profile</h3><p>Current: <strong>'+esc(loc.stockProfile||'Standard Service Van')+'</strong></p><div class="inv-inline"><select data-inv-profile-select="'+esc(loc.id)+'">'+profiles.map(p=>'<option '+((state.profilePreview||loc.stockProfile||'Standard Service Van')===p?'selected':'')+'>'+esc(p)+'</option>').join('')+'</select><button class="secondary" data-inv-preview-profile="'+esc(loc.id)+'">Preview</button></div><small>Standard Service Van · Installation Van · Summer Service · Winter Service</small></div><div><h3>Count reminder</h3><p>Count cadence: <strong>'+inv.countState(loc.id).cadenceDays+' days</strong></p><button class="secondary" data-inv-start-count="'+esc(loc.id)+'">Schedule / start count</button></div><div><h3>Smart Min suggestions</h3><p>'+smart.length+' suggestion'+(smart.length===1?'':'s')+' based on usage and Project demand.</p><button class="secondary" data-inv-smart-min="'+esc(loc.id)+'">Review suggestion</button></div></div>'+profilePreviewHtml(loc)+smartMinHtml(loc,smart)+'</section>';}
function profilePreviewHtml(loc){if(!state.profilePreview)return '';const preview=inv.profilePreview(loc.id,state.profilePreview);const changed=preview.filter(x=>x.from.min!==x.to.min||x.from.target!==x.to.target||x.from.max!==x.to.max);return '<div class="inventory-profile-preview"><div><strong>'+esc(state.profilePreview)+' profile preview</strong><span>'+changed.length+' threshold lines would change. Nothing has been applied.</span></div><button data-inv-apply-profile="'+esc(loc.id)+'|'+esc(state.profilePreview)+'">Apply profile rules</button></div>';}
function smartMinHtml(loc,smart){if(!state.smartMinProductId)return '';const s=smart.find(x=>x.productId===state.smartMinProductId)||smart[0];if(!s)return '<div class="inventory-profile-preview"><div><strong>Smart Min</strong><span>No threshold change is suggested right now.</span></div></div>';return '<div class="inventory-smart-min"><div><span>Smart Min / Review suggestion</span><strong>'+esc(s.sku)+': '+s.currentMin+' → '+s.suggestedMin+'</strong><small>'+esc(s.reason)+' Monthly usage '+s.monthlyUsage+' · Project demand '+s.projectDemand+'.</small></div><button data-inv-apply-smart-min="'+esc(loc.id)+'|'+esc(s.productId)+'|'+s.suggestedMin+'">Apply Min</button></div>';}
function alertAction(a){if(a.action==='Create Top-Up Transfer'){const row=inv.locationRows(a.locationId).find(r=>r.productId===a.productId);return '<button data-inv-topup="'+esc(a.locationId)+'|'+esc(a.productId)+'|'+n(row?.suggestedTopUp)+'">Create Top-Up Transfer</button>';}if(a.action==='Review Replenishment')return '<button data-inv-open-replenishment>Review Replenishment</button>';if(a.action==='Schedule count')return '<button data-inv-start-count="'+esc(a.locationId)+'">Schedule count</button>';if(a.action==='Return excess stock'){const row=inv.locationRows(a.locationId).find(r=>r.productId===a.productId);return '<button data-inv-return="'+esc(a.locationId)+'|'+esc(a.productId)+'|'+n(row?.returnSuggested)+'">Return excess stock</button>';}if(a.action==='Stage Project Stock'){const row=inv.locationRows(a.locationId).find(r=>r.productId===a.productId),qty=Math.max(0,n(row?.projectDemand)-n(row?.available));return '<button data-inv-topup="'+esc(a.locationId)+'|'+esc(a.productId)+'|'+qty+'">Stage Project Stock</button>';}return '<button class="secondary" data-inv-section="Missing / Damaged">Investigate variance</button>';}
function overviewPage(){const alerts=inv.alerts(),critical=alerts.filter(a=>a.severity==='critical'),warnings=alerts.filter(a=>a.severity==='warning'),vans=(d().locations||[]).filter(l=>l.type==='Engineer Van');const vanRows=vans.map(l=>{const r=inv.vanReadiness(l.id),s=inv.locationSummary(l.id);return '<tr><td><button class="link-button" data-inv-open-location="'+esc(l.id)+'"><strong>'+esc(l.name)+'</strong></button><small>'+esc(l.owner||'')+'</small></td><td><strong>'+r.readinessPct+'%</strong><small>'+r.belowMin+' below Min</small></td><td>'+r.topUpUnits+'</td><td>'+r.projectDemand+'</td><td>'+cash(s.missingDamagedValue)+'</td><td>'+pill(s.count.due?'Count due':'Current',s.count.due?'warn':'good')+'</td></tr>';}).join('');return header('Inventory Overview','Company-wide stock health, engineer readiness, Project stock and exceptions.','<button data-inv-open-warehouse>Open Warehouse</button>')+companyMetrics()+'<section class="inventory-overview-grid"><main><section class="inventory-card"><header><div><h2>Engineer Stock Readiness</h2><p>Min levels, Project demand and count status across every van.</p></div><button data-inv-section="Engineer Vans">Engineer Vans</button></header><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Van</th><th>Readiness</th><th>Top-up units</th><th>Project demand</th><th>Missing / damaged</th><th>Count</th></tr></thead><tbody>'+vanRows+'</tbody></table></div></section></main><aside><section class="inventory-card"><header><div><h2>Priority Alerts</h2><p>'+critical.length+' critical · '+warnings.length+' warning</p></div></header><div class="inventory-alert-list">'+alerts.filter(a=>a.severity!=='info').slice(0,8).map(a=>'<div class="inventory-alert '+esc(a.severity)+'"><div><strong>'+esc(a.title)+'</strong><p>'+esc(locName(a.locationId))+' · '+esc(a.reason)+'</p></div>'+alertAction(a)+'</div>').join('')+'</div></section></aside></section>';}
function stockPage(){const match=searchMatch(),products=(d().products||[]).filter(p=>p&&!p.deleted&&match([p.name,p.sku,p.supplierSku,p.barcode,p.mpn]));const rows=products.map(p=>{const stock=(d().stock||[]).filter(r=>r.productId===p.id),on=stock.reduce((x,r)=>x+n(r.qty),0),al=stock.reduce((x,r)=>x+n(r.allocated),0),av=stock.reduce((x,r)=>x+Math.max(0,n(r.qty)-n(r.allocated)),0),locs=stock.filter(r=>n(r.qty)>0).length,po=openPoForProduct(p.id),inbound=global.PoolShedProductHub?global.PoolShedProductHub.confirmedInbound(p.id):0;return '<tr><td><button class="link-button" data-inv-open-product="'+esc(p.id)+'"><strong>'+esc(p.name)+'</strong></button><small>'+esc(p.sku)+'</small></td><td>'+on+'</td><td>'+al+'</td><td><strong>'+av+'</strong></td><td>'+inbound+(po?'<small><button class="link-button" data-inv-open-po="'+esc(po.id)+'">'+esc(po.id)+'</button></small>':'')+'</td><td>'+locs+'</td><td>'+cash(on*n(p.cost))+'</td><td><button data-inv-stock-locations="'+esc(p.id)+'">View locations</button></td></tr>';}).join('');return header('Stock','Fast company-wide availability lookup with direct links to Product Details and inbound Purchase Orders.')+'<div class="inventory-toolbar"><div class="inventory-search"><span>⌕</span><input data-inv-search placeholder="Search product, SKU, supplier SKU, barcode…" value="'+esc(state.query)+'"></div><button class="secondary" data-inv-open-replenishment>Product Hub Replenishment</button></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Product</th><th>On Hand</th><th>Allocated</th><th>Available</th><th>Inbound</th><th>Locations</th><th>Stock Value</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';}
function transfersPage(){const locs=(d().locations||[]).filter(l=>l.type==='Engineer Van'),rows=locs.flatMap(l=>inv.locationRows(l.id).filter(r=>r.suggestedTopUp>0||r.returnSuggested>0).map(r=>({l,r}))).map(x=>'<tr><td><button class="link-button" data-inv-open-location="'+esc(x.l.id)+'">'+esc(x.l.name)+'</button></td><td><button class="link-button" data-inv-open-product="'+esc(x.r.productId)+'">'+esc(x.r.name)+'</button><small>'+esc(x.r.sku)+'</small></td><td>'+x.r.available+'</td><td>'+x.r.min+' / '+x.r.target+' / '+x.r.max+'</td><td>'+x.r.warehouseAvailable+'</td><td><strong>'+(x.r.suggestedTopUp?'+ '+x.r.suggestedTopUp:'- '+x.r.returnSuggested)+'</strong></td><td>'+(x.r.suggestedTopUp?'<button data-inv-topup="'+esc(x.l.id)+'|'+esc(x.r.productId)+'|'+x.r.suggestedTopUp+'">Create Top-Up Transfer</button>':'<button class="secondary" data-inv-return="'+esc(x.l.id)+'|'+esc(x.r.productId)+'|'+x.r.returnSuggested+'">Return excess stock</button>')+'</td></tr>').join('')||'<tr><td colspan="7" class="inv-empty">No engineer van transfer recommendations right now.</td></tr>';return header('Transfers & Top-Ups','Internal stock positioning only. Supplier replenishment remains in Product Hub / Purchasing.','<button class="secondary" data-inv-open-replenishment>Review supplier replenishment</button>')+'<section class="inventory-card"><header><div><h2>Suggested internal moves</h2><p>Recommendations respect free Warehouse stock and live van Min / Target / Max.</p></div></header><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Location</th><th>Product</th><th>Free now</th><th>Min / Target / Max</th><th>Warehouse free</th><th>Suggested Move</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></section>';}
function cycleCountsPage(){const rows=(d().locations||[]).map(l=>{const s=inv.locationSummary(l.id);return '<tr><td><button class="link-button" data-inv-open-location="'+esc(l.id)+'"><strong>'+esc(l.name)+'</strong></button><small>'+esc(l.type)+'</small></td><td>'+esc(s.count.lastCounted||'Never')+'</td><td>'+s.count.cadenceDays+' days</td><td>'+s.varianceCount+'</td><td>'+cash(s.missingDamagedValue)+'</td><td>'+pill(s.count.due?'Count Due':'Current',s.count.due?'warn':'good')+'</td><td><button data-inv-start-count="'+esc(l.id)+'">Start / Continue Count</button></td></tr>';}).join('');return header('Cycle Counts','Expected → counted → variance → reason → approval/recount → auditable stock movement.')+'<div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Location</th><th>Last Counted</th><th>Cadence</th><th>Variance events</th><th>Missing / damaged value</th><th>Status</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';}
function movementsPage(){const match=searchMatch(),rows=(d().movements||[]).slice().reverse().filter(m=>{const p=(d().products||[]).find(p=>p.id===m.productId);return match([m.date,m.type,p?.sku,p?.name,m.from,m.to,m.ref,m.user,m.note]);}).slice(0,250).map(m=>{const p=(d().products||[]).find(p=>p.id===m.productId);return '<tr><td>'+esc(m.date)+'</td><td>'+pill(m.type,'info')+'</td><td>'+(p?'<button class="link-button" data-inv-open-product="'+esc(p.id)+'">'+esc(p.sku)+'</button>':esc(m.productId))+'<small>'+esc(p?.name||'')+'</small></td><td>'+n(m.qty)+'</td><td>'+esc(m.from)+'</td><td>'+esc(m.to)+'</td><td>'+esc(m.ref||'')+'</td><td>'+esc(m.user||'')+'</td><td>'+esc(m.note||'')+'</td></tr>';}).join('');return header('Stock Movements','Every transfer, receipt, issue, adjustment and approved count remains traceable.')+'<div class="inventory-toolbar"><div class="inventory-search"><span>⌕</span><input data-inv-search placeholder="Search SKU, movement, location, reference…" value="'+esc(state.query)+'"></div></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Date</th><th>Movement</th><th>Product</th><th>Qty</th><th>From</th><th>To</th><th>Reference</th><th>User</th><th>Note</th></tr></thead><tbody>'+rows+'</tbody></table></div>';}
function exceptionsPage(kind){let list=inv.alerts();if(kind==='Missing / Damaged')list=list.filter(a=>a.type==='repeated-variance'||a.title.toLowerCase().includes('damage'));const html=list.map(a=>'<div class="inventory-alert-row"><div>'+pill(a.severity,a.severity==='critical'?'bad':a.severity==='warning'?'warn':'info')+'</div><div><strong>'+esc(a.title)+'</strong><small>'+esc(locName(a.locationId))+(a.productId?' · '+esc((inv.product(a.productId)||{}).sku||a.productId):'')+'</small><p>'+esc(a.reason)+'</p></div><div>'+alertAction(a)+'</div></div>').join('')||'<div class="inventory-empty-card">No matching Inventory exceptions.</div>';return header(kind,kind==='Missing / Damaged'?'Investigate repeated variance, damage and value loss by location/product.':'Actionable reminders and stock exceptions. Every alert explains the reason and next action.')+'<section class="inventory-card"><div class="inventory-exception-list">'+html+'</div></section>';}
function page(){if(state.locationId)return locationDetail(state.locationId);const sub=current();if(sub==='Overview')return overviewPage();if(sub==='Stock')return stockPage();if(sub==='Engineer Vans')return locationsPage('Engineer Van');if(sub==='Project Stock')return locationsPage('Job Bin');if(sub==='Transfers & Top-Ups')return transfersPage();if(sub==='Cycle Counts')return cycleCountsPage();if(sub==='Missing / Damaged')return exceptionsPage('Missing / Damaged');if(sub==='Stock Movements')return movementsPage();if(sub==='Exceptions & Alerts')return exceptionsPage('Exceptions & Alerts');return locationsPage();}
if(legacySidebarSubGroups)sidebarSubGroups=function(id){if(id==='locations')return sections.slice();return legacySidebarSubGroups(id);};
if(legacyOpenSidebarSubGroup)openSidebarSubGroup=function(tabId,subgroup){if(tabId==='locations'){active='locations';activeSubPage.locations=sections.includes(subgroup)?subgroup:'Locations';state.locationId='';inventoryView='overview';selectedInventoryLocationId='';render();return;}return legacyOpenSidebarSubGroup(tabId,subgroup);};
renderLocations=function(){if(['stocktake','manager','location','manage-locations'].includes(inventoryView)){inventoryView=inventoryView==='stocktake'?'location':inventoryView==='manager'?'manage-locations':inventoryView;return legacyRenderLocations();}const day=new Date().toISOString().slice(0,10);if(state.remindersDay!==day){state.remindersDay=day;inv.ensureReminders({today:day});}const screen=document.getElementById('screen-locations');const content='<div class="inventory-control-v112">'+page()+'</div>';if(screen)screen.innerHTML=content;return content;};
let inputTimer=null;
document.addEventListener('input',function(e){const q=e.target.closest('[data-inv-search]');if(q){state.query=q.value;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{if(active==='locations')renderLocations();},120);return;}const th=e.target.closest('[data-inv-threshold]');if(th){th.dataset.invDirty='true';}});
document.addEventListener('change',function(e){const f=e.target.closest('[data-inv-location-type]');if(f){state.locationType=f.value;renderLocations();return;}const p=e.target.closest('[data-inv-profile-select]');if(p){state.profilePreview=p.value;}});
document.addEventListener('click',function(e){const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-inv-section')){setSection(b.dataset.invSection);return;}
 if(b.hasAttribute('data-inv-open-location')){state.locationId=b.dataset.invOpenLocation;renderLocations();return;}
 if(b.hasAttribute('data-inv-back-locations')){state.locationId='';renderLocations();return;}
 if(b.hasAttribute('data-inv-manage-locations')){inventoryView='manage-locations';render();return;}
 if(b.hasAttribute('data-inv-open-product')){active='products';selectedProductId=b.dataset.invOpenProduct;productView='profile';if(global.poolShedProductHubV111State)global.poolShedProductHubV111State.productTab='Overview';render();return;}
 if(b.hasAttribute('data-inv-open-project')){active='jobs';activeSubPage.jobs='Projects';if(typeof psProjectSelected!=='undefined')psProjectSelected=b.dataset.invOpenProject;render();return;}
 if(b.hasAttribute('data-inv-open-po')){active='purchase';activeSubPage.purchase='Purchase Orders';selectedPurchaseOrderId=b.dataset.invOpenPo;purchaseOrderView='detail';render();return;}
 if(b.hasAttribute('data-inv-open-replenishment')){active='products';activeSubPage.products='Replenishment';productView='list';render();return;}
 if(b.hasAttribute('data-inv-open-warehouse')){active='warehouse';activeSubPage.warehouse='Transfers';render();return;}
 if(b.hasAttribute('data-inv-open-transfers')){state.locationId='';activeSubPage.locations='Transfers & Top-Ups';renderLocations();return;}
 if(b.hasAttribute('data-inv-start-count')){selectedInventoryLocationId=b.dataset.invStartCount;inventoryView='location';render();return;}
 if(b.hasAttribute('data-inv-topup')){const [loc,pid,qty]=b.dataset.invTopup.split('|');const result=inv.createTopUpTransfer(loc,pid,n(qty));notify(result.ok?'Top-up transfer completed and movement logged.':(result.moved?result.moved+' moved; '+result.remaining+' still short.':result.reason||'Top-up could not be completed.'));render();return;}
 if(b.hasAttribute('data-inv-return')){const [loc,pid,qty]=b.dataset.invReturn.split('|');const result=inv.createReturnTransfer(loc,pid,n(qty));notify(result.ok?'Excess stock returned to Warehouse and movement logged.':result.reason||'Return transfer could not be completed.');render();return;}
 if(b.hasAttribute('data-inv-save-threshold')){const [pid,lid]=b.dataset.invSaveThreshold.split('|');let rule=(d().restockRules||[]).find(r=>r.productId===pid&&r.locationId===lid);if(!rule){rule={productId:pid,locationId:lid,min:0,restockTo:0,max:0,priority:'Normal'};(d().restockRules||(d().restockRules=[])).push(rule);}document.querySelectorAll('[data-inv-threshold^="'+pid+'|'+lid+'|"]').forEach(i=>{const key=i.dataset.invThreshold.split('|')[2];rule[key]=Math.max(0,Math.floor(n(i.value)));});if(rule.restockTo<rule.min)rule.restockTo=rule.min;if(rule.max<rule.restockTo)rule.max=rule.restockTo;save();notify('Location Min / Target / Max saved.');renderLocations();return;}
 if(b.hasAttribute('data-inv-preview-profile')){const lid=b.dataset.invPreviewProfile,select=document.querySelector('[data-inv-profile-select="'+lid+'"]');state.profilePreview=select?select.value:'Standard Service Van';renderLocations();return;}
 if(b.hasAttribute('data-inv-apply-profile')){const [lid,name]=b.dataset.invApplyProfile.split('|'),loc=inv.location(lid),preview=inv.profilePreview(lid,name);if(!loc)return;if(global.confirm&&!global.confirm('Apply '+name+' Min / Target / Max suggestions to '+loc.name+'?'))return;preview.forEach(x=>{let rule=(d().restockRules||[]).find(r=>r.productId===x.productId&&r.locationId===lid);if(rule){rule.min=x.to.min;rule.restockTo=x.to.target;rule.max=x.to.max;}});loc.stockProfile=name;loc.countCadenceDays=inv.profiles[name]?.countCadenceDays||loc.countCadenceDays;save();state.profilePreview='';notify(name+' profile rules applied after review.');renderLocations();return;}
 if(b.hasAttribute('data-inv-smart-min')){const lid=b.dataset.invSmartMin,s=inv.smartThresholdSuggestions(lid);state.smartMinProductId=s[0]?.productId||'';renderLocations();return;}
 if(b.hasAttribute('data-inv-apply-smart-min')){const [lid,pid,value]=b.dataset.invApplySmartMin.split('|');let rule=(d().restockRules||[]).find(r=>r.productId===pid&&r.locationId===lid);if(!rule)return;if(global.confirm&&!global.confirm('Apply suggested Min '+value+' to this van SKU?'))return;rule.min=Math.max(0,Math.floor(n(value)));if(rule.restockTo<rule.min)rule.restockTo=rule.min;if(rule.max<rule.restockTo)rule.max=rule.restockTo;save();state.smartMinProductId='';notify('Smart Min applied after review.');renderLocations();return;}
 if(b.hasAttribute('data-inv-stock-locations')){const pid=b.dataset.invStockLocations,row=(d().stock||[]).find(r=>r.productId===pid&&n(r.qty)>0);if(row){state.locationId=row.locationId;activeSubPage.locations='Locations';renderLocations();}return;}
});
global.PoolShedInventoryWorkspace={version:'1.12.0',sections,state,render:page};
})(globalThis);
